    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }
}

void loop() {
  DateTime now = rtc.now();
  Serial.print(now.timestamp(DateTime::TIMESTAMP_FULL));
  Serial.print("  ");
  Serial.print(rtc.getTemperature());
  Serial.println(" C");
  delay(1000);
}

